describe('Past Date Field Validation', () => {
  beforeEach(() => {
    cy.visit('/form');
    cy.get('form').should('be.visible');
  });

  it('should display error when submitting a future date in past-date field', () => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const formattedDate = tomorrow.toISOString().split('T')[0];

    cy.get('input[name="past-date"]').type(formattedDate);
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Date must be in the past');

    cy.get('input[name="past-date"]').should('have.attr', 'aria-invalid', 'true');
  });

  it('should accept a valid past date and submit successfully', () => {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const formattedDate = yesterday.toISOString().split('T')[0];

    cy.get('input[name="past-date"]').type(formattedDate);
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Form submitted successfully');
  });

  it('should display error when submitting todays date in past-date field', () => {
    const today = new Date();
    const formattedDate = today.toISOString().split('T')[0];

    cy.get('input[name="past-date"]').type(formattedDate);
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Date must be in the past');
  });

  it('should clear error message when correcting the date input', () => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const futureDate = tomorrow.toISOString().split('T')[0];

    cy.get('input[name="past-date"]').type(futureDate);
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');

    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    const pastDate = yesterday.toISOString().split('T')[0];

    cy.get('input[name="past-date"]').clear().type(pastDate);
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
